+/**
+ * Parses batch records from a CSV file and allocates memory to store the parsed data.
+ *
+ * This function processes CSV file content uploaded by the user and constructs a parsing buffer
+ * based on the number of records and the field sizes of each record. It automatically calculates
+ * the required memory size and allocates an appropriate buffer to store the parsed data.
+ *
+ * @param record_count Number of CSV records to parse
+ * @param field_sizes Integer array storing the size (in bytes) of each field in a record
+ * @param csv_data String array storing raw CSV data, where each element represents one CSV record
+ * @param parsed_buffer Double pointer to char; the function will allocate memory at the location
+ *                      pointed to by this parameter and store the parsed data there.
+ *
+ * @return Returns 0 on successful parsing, -1 on failure.
+ */
+int parse_csv_records(int record_count, int* field_sizes, char** csv_data, char** parsed_buffer)
+{
+    int i, r;
+    int num_fields = 0;
+    int record_size = 0;
+    size_t total_size;
+    char *buffer;
+    char *record_copy;
+    char *token;
+    char *ptr;
+    char *comma;
+    int offset;
+    int field_idx;
+    size_t field_len;
+    size_t copy_len;
+    const char *p;
+
+    /* Validate parameters */
+    if (record_count <= 0 || field_sizes == NULL || csv_data == NULL || parsed_buffer == NULL) {
+        return -1;
+    }
+
+    /* Validate csv_data entries */
+    for (i = 0; i < record_count; i++) {
+        if (csv_data[i] == NULL) {
+            return -1;
+        }
+    }
+
+    /* Count number of fields from the first CSV record */
+    p = csv_data[0];
+    if (p[0] == '\0') {
+        return -1;
+    }
+    num_fields = 1;
+    while (*p != '\0') {
+        if (*p == ',') {
+            num_fields++;
+        }
+        p++;
+    }
+
+    /* Calculate the size of each record */
+    for (i = 0; i < num_fields; i++) {
+        if (field_sizes[i] <= 0) {
+            return -1;
+        }
+        record_size += field_sizes[i];
+    }
+
+    /* Allocate the parsing buffer */
+    total_size = (size_t)record_count * (size_t)record_size;
+    buffer = (char *)malloc(total_size);
+    if (buffer == NULL) {
+        return -1;
+    }
+
+    /* Initialize buffer to zero */
+    memset(buffer, 0, total_size);
+
+    /* Parse each record and store into buffer */
+    for (r = 0; r < record_count; r++) {
+        record_copy = (char *)malloc(strlen(csv_data[r]) + 1);
+        if (record_copy == NULL) {
+            free(buffer);
+            return -1;
+        }
+        strcpy(record_copy, csv_data[r]);
+
+        ptr = record_copy;
+        offset = 0;
+
+        for (field_idx = 0; field_idx < num_fields; field_idx++) {
+            if (*ptr != '\0') {
+                comma = strchr(ptr, ',');
+                if (comma != NULL) {
+                    *comma = '\0';
+                    token = ptr;
+                    ptr = comma + 1;
+                } else {
+                    token = ptr;
+                    ptr = ptr + strlen(ptr);
+                }
+
+                field_len = strlen(token);
+                if (field_len < (size_t)field_sizes[field_idx]) {
+                    copy_len = field_len;
+                } else {
